            {step === 'backup' ? <div className='py-2'><ShieldCheck className='h-11 w-11 text-emerald-700' /><h2 className='mt-4 text-xl font-bold'>{ui.backupTitle}</h2><p className='mt-2 text-sm leading-6 text-slate-600'>{ui.backupBody}</p><ul className='mt-5 grid list-none grid-cols-2 gap-2 rounded-2xl bg-slate-950 p-4 text-center font-mono text-sm font-bold text-white'>{backupCodes.map((item) => <li key={item} className='list-none rounded-lg bg-white/10 px-2 py-2'>{item}</li>)}</ul><button type='button' onClick={() => { void navigator.clipboard.writeText(backupCodes.join('\n')).then(() => setCopied(true)); }} className='mt-3 flex min-h-11 w-full items-center justify-center gap-2 rounded-xl border border-slate-300 px-4 text-sm font-semibold text-slate-700'><Copy className='h-4 w-4' />{copied ? ui.copied : ui.copy}</button><label className='mt-5 flex items-start gap-3 text-sm leading-6 text-slate-700'><input type='checkbox' checked={backupSaved} onChange={(event) => setBackupSaved(event.target.checked)} className='mt-1 h-5 w-5 accent-emerald-700' />{ui.saved}</label><button type='button' disabled={!backupSaved} onClick={() => window.location.assign(GEKTA_PATHS[initialLocale])} className='mt-5 min-h-12 w-full rounded-xl bg-emerald-800 px-5 text-sm font-bold text-white disabled:cursor-not-allowed disabled:opacity-40'>{ui.continue}</button></div> : null}
          </div>
        </section>
      </div>
    </main>
  );
}

import { randomUUID } from 'node:crypto';
import { verifyGektaConsentSnapshot } from '../../../../../../../packages/domain-core/src/gekta-consent-evidence';
import { currentGektaLegalEvidence } from '@/lib/gekta/consent-evidence-server';
import { sendTransactionalMail, isTransactionalMailConfigured } from '@/lib/server/transactional-mail';
import { assertCsrf, resolveRequestTargetOrigin } from '@/lib/server-request-security';
import {
  GEKTA_AUTH_TIMEOUT_MS,
  accountHash,
  gektaApiBase,
  gektaAuthJson,
  gektaForwardHeaders,
  registrationDeliveryKey,
  readGektaAuthJson,
  safeLocale,
  validEmail,
} from '@/lib/server/gekta-auth-route';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 15;

const COPY = {
  ru: {
    subject: 'Гекта — подтвердите email',
    intro: 'Получен запрос на регистрацию в Гекте.',
    action: 'Подтвердите email по одноразовой ссылке:',
    expiry: 'Ссылка действует 30 минут. Затем настройте обязательный второй фактор, и начнётся 30-дневный пробный период.',
  },
  en: {
    subject: 'Gekta — confirm your email',
    intro: 'A request to create a Gekta account was received.',
    action: 'Confirm your email using this single-use link:',
    expiry: 'The link is valid for 30 minutes. Next, set up the required second factor to start the 30-day trial.',
  },
  zh: {
    subject: 'Gekta — 确认电子邮箱',
    intro: '已收到创建 Gekta 账户的请求。',
    action: '请使用以下一次性链接确认电子邮箱：',
    expiry: '链接有效期为30分钟。随后设置必需的双重验证，即可开始30天试用。',
  },
} as const;

type ApiPayload = {
  status?: string;
  emailDelivery?: { email?: string; token?: string };
  code?: string;
};

export async function POST(request: Request) {
  const correlationId = request.headers.get('x-correlation-id') || randomUUID();
  if (!assertCsrf(request).ok) return gektaAuthJson({ accepted: false, code: 'CSRF_REJECTED', correlationId }, 403);

  const body = await readGektaAuthJson(request);
  if (!body) return gektaAuthJson({ accepted: false, code: 'REGISTRATION_REQUEST_INVALID', correlationId }, 400);
  const email = String(body.email || '').trim().toLowerCase();
  const fullName = String(body.fullName || '').trim();
  const phone = String(body.phone || '').trim();
  const password = String(body.password || '');
  const locale = safeLocale(body.locale);
  const passwordClasses = [/[a-z]/u, /[A-Z]/u, /\d/u, /[^A-Za-z0-9]/u]
    .filter((pattern) => pattern.test(password)).length;
  const phoneDigits = phone.replace(/\D/gu, '');
  if (
    !validEmail(email)
    || fullName.length < 2
    || fullName.length > 120
    || phone.length > 32
    || phoneDigits.length < 10
    || phoneDigits.length > 15
    || password.length < 12
    || password.length > 128
    || passwordClasses < 3
    || body.acceptedServiceTerms !== true
    || body.acceptedPersonalData !== true
  ) {
    return gektaAuthJson({ accepted: false, code: 'REGISTRATION_REQUEST_INVALID', correlationId }, 400);
  }

  const upstream = gektaApiBase();
  const deliveryKey = registrationDeliveryKey();
  if (!upstream || deliveryKey.length < 32 || !isTransactionalMailConfigured()) {
    console.error('gekta_registration_configuration_error', JSON.stringify({
      correlationId,
      apiConfigured: Boolean(upstream),
      deliveryBoundaryConfigured: deliveryKey.length >= 32,
      mailConfigured: isTransactionalMailConfigured(),
    }));
    return gektaAuthJson({ accepted: false, code: 'REGISTRATION_SERVICE_UNAVAILABLE', correlationId }, 503);
  }

  const consentEvidence = currentGektaLegalEvidence(locale, 'GEKTA_REGISTRATION');
  if (!verifyGektaConsentSnapshot(body.consentSnapshot, consentEvidence, deliveryKey)) {
    return gektaAuthJson({ accepted: false, code: 'CONSENT_REFRESH_REQUIRED', correlationId }, 400);
  }

  try {
    const response = await fetch(`${upstream}/gekta/auth/register`, {
      method: 'POST',
      headers: gektaForwardHeaders(request, correlationId, { deliveryKey }),
      body: JSON.stringify({
        email,
        fullName,
        phone,
        password,
        acceptedServiceTerms: true,
        acceptedPersonalData: true,
        consentSnapshot: body.consentSnapshot,
        consentEvidence,
      }),
      cache: 'no-store',
      redirect: 'manual',
      signal: AbortSignal.timeout(GEKTA_AUTH_TIMEOUT_MS),
    });
    if (response.status >= 300 && response.status < 400) {
      return gektaAuthJson({ accepted: false, code: 'REGISTRATION_SERVICE_UNAVAILABLE', correlationId }, 502);
    }
    const payload = await response.json().catch(() => ({} as ApiPayload)) as ApiPayload;
    if (!response.ok) {
      const status = response.status === 429 ? 429 : response.status >= 500 ? 503 : 400;
      console.warn('gekta_registration_api_rejected', JSON.stringify({
        correlationId,
        status: response.status,
        accountHash: accountHash(email),
      }));
      return gektaAuthJson({
        accepted: false,
        code: status === 429 ? 'RATE_LIMITED' : status === 503 ? 'REGISTRATION_SERVICE_UNAVAILABLE'
          : response.status === 400 && payload?.code === 'CONSENT_REFRESH_REQUIRED' ? 'CONSENT_REFRESH_REQUIRED' : 'REGISTRATION_REQUEST_INVALID',
        correlationId,
      }, status);
    }

    const delivery = payload.emailDelivery;
    if (delivery?.email && delivery.token) {
      const origin = resolveRequestTargetOrigin(request);
      if (!origin) return gektaAuthJson({ accepted: false, code: 'REGISTRATION_SERVICE_UNAVAILABLE', correlationId }, 503);
      const verifyUrl = new URL('/api/gekta/auth/email/verify', origin);
      verifyUrl.searchParams.set('token', delivery.token);
      verifyUrl.searchParams.set('lang', locale);
      const copy = COPY[locale];
      const delivered = await sendTransactionalMail({
        to: delivery.email,
        subject: copy.subject,
        text: [copy.intro, '', copy.action, verifyUrl.toString(), '', copy.expiry].join('\n'),
      });
      console.info('gekta_registration_email_delivery_result', JSON.stringify({
        correlationId,
        accountHash: accountHash(email),
        delivered: delivered.delivered,
        provider: delivered.provider,
        reason: delivered.reason,
      }));
      if (!delivered.delivered) {
        return gektaAuthJson({ accepted: false, code: 'REGISTRATION_EMAIL_DELIVERY_UNAVAILABLE', correlationId }, 503);
      }
    } else {
      // Unknown/already-used email and a newly accepted email deliberately have
      // the same public response. The bearer token never crosses this BFF.
      console.info('gekta_registration_public_request_accepted', JSON.stringify({
        correlationId,
        accountHash: accountHash(email),
      }));
    }

    return gektaAuthJson({
      accepted: true,
      status: 'EMAIL_VERIFICATION_REQUIRED',
      correlationId,
    }, 202);
  } catch (error) {
    console.error('gekta_registration_transport_failure', JSON.stringify({
      correlationId,
      accountHash: accountHash(email),
      reason: error instanceof Error ? error.name : 'unknown',
    }));
    return gektaAuthJson({ accepted: false, code: 'REGISTRATION_SERVICE_UNAVAILABLE', correlationId }, 503);
  }
}

import type { Metadata } from 'next';
import Link from 'next/link';
import { notFound } from 'next/navigation';
import { ArrowLeft } from 'lucide-react';
import { GEKTA_LEGAL_DOCUMENTS, GEKTA_LEGAL_VERSION, getGektaLegalDocument, renderLegalDocument } from '@/lib/gekta/legal';
import { getMerchantProfile } from '@/lib/gekta/merchant';
import { legalContentHash, renderedLegalDocumentHash } from '../../../../../packages/domain-core/src/gekta-consent-evidence';

export const dynamicParams = false;
export const dynamic = 'force-dynamic';

type PageProps = Readonly<{ params: Promise<{ slug: string }>; searchParams?: Promise<{ v?: string; h?: string; p?: string }> }>;

export function generateStaticParams() {
  return GEKTA_LEGAL_DOCUMENTS.map(({ slug }) => ({ slug }));
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { slug } = await params;
  const document = getGektaLegalDocument(slug);
  if (!document) return {};
  return {
    title: `${document.title} — Гекта`,
    description: document.description,
    alternates: { canonical: `/legal/${document.slug}` },
    robots: { index: true, follow: true },
  };
}

export default async function GektaLegalDocumentPage({ params, searchParams }: PageProps) {
  const { slug } = await params;
  const found = getGektaLegalDocument(slug);
  if (!found) notFound();
  // Реквизиты исполнителя приходят из профиля продавца, а не из текста документа.
  const profile = getMerchantProfile();
  const document = renderLegalDocument(found, profile);
  const commitment = await searchParams;
  if (commitment && (commitment.v !== undefined || commitment.h !== undefined || commitment.p !== undefined)) {
    const profileHash = legalContentHash(profile);
    if (commitment.v !== GEKTA_LEGAL_VERSION || commitment.p !== profileHash.slice(7)
      || commitment.h !== renderedLegalDocumentHash(GEKTA_LEGAL_VERSION, profileHash, document).slice(7)) notFound();
  }

  return (
    <main className='min-h-screen bg-[#fbfaf5] text-slate-950'>
      <div className='mx-auto max-w-3xl px-4 py-10 sm:px-6 sm:py-16'>
        <Link href='/gekta' className='inline-flex min-h-11 items-center gap-2 rounded-full px-3 text-sm font-semibold text-emerald-800 hover:bg-emerald-50'>
          <ArrowLeft className='h-4 w-4' aria-hidden='true' />Гекта
        </Link>
        <h1 className='mt-8 text-balance text-3xl font-semibold tracking-[-0.03em] sm:text-4xl'>{document.title}</h1>
        <p className='mt-4 text-base leading-7 text-slate-600'>{document.summary}</p>
        <p className='mt-3 text-xs text-slate-500'>Редакция {GEKTA_LEGAL_VERSION}</p>

        <div className='mt-10 space-y-8'>
          {document.sections.map((section) => (
            <section key={section.heading}>
              <h2 className='text-lg font-semibold text-slate-950'>{section.heading}</h2>
              {section.paragraphs.map((paragraph) => (
                <p key={paragraph} className='mt-3 leading-7 text-slate-700'>{paragraph}</p>
              ))}
            </section>
          ))}
        </div>

        <nav className='mt-14 border-t border-slate-200 pt-6' aria-label='Документы Гекты'>
          <h2 className='text-sm font-semibold text-slate-900'>Другие документы</h2>
          <ul className='mt-3 space-y-2'>
            {GEKTA_LEGAL_DOCUMENTS.filter((item) => item.slug !== document.slug).map((item) => (
              <li key={item.slug}>
                <Link href={`/legal/${item.slug}`} className='text-sm font-medium text-emerald-800 underline-offset-4 hover:underline'>{item.title}</Link>
              </li>
            ))}
            <li><Link href='/platform-v7/contact' className='text-sm font-medium text-emerald-800 underline-offset-4 hover:underline'>Контакты поддержки</Link></li>
          </ul>
        </nav>
      </div>
    </main>
  );
}

import { Body, Controller, Headers, HttpCode, Ip, Post } from '@nestjs/common';
import { Public } from '../../common/decorators/public.decorator';
import { RateLimit } from '../../common/decorators/rate-limit.decorator';
import { GektaRegistrationService } from './gekta-registration.service';
import { ProductSessionService } from './product-session.service';

/**
 * Регистрация и вход в Гекту.
 *
 * Маршруты публичные по необходимости — до регистрации сессии не существует.
 * Всё остальное решает сервер: пароль, подтверждение email и обязательный
 * MFA. Ни один шаг не выдаёт активную сессию раньше, чем пройдены все три.
 */
@Controller('gekta/auth')
export class GektaRegistrationController {
  constructor(
    private readonly registration: GektaRegistrationService,
    private readonly productSessions: ProductSessionService,
  ) {}

  @Public()
  @HttpCode(202)
  @RateLimit({ name: 'gekta_register', scope: 'ip', limit: 5, windowSeconds: 300, limitEnv: 'RATE_LIMIT_GEKTA_REGISTER', windowEnv: 'RATE_LIMIT_WINDOW_SECONDS' })
  @Post('register')
  register(
    @Body() body: {
      email?: string;
      password?: string;
      fullName?: string;
      phone?: string;
      acceptedServiceTerms?: boolean;
      acceptedPersonalData?: boolean;
      consentSnapshot?: unknown;
      consentEvidence?: unknown;
    },
    @Headers('x-registration-delivery-key') deliveryKey?: string,
    @Headers('user-agent') userAgent?: string,
    @Ip() ip?: string,
  ) {
    return this.registration.register({
      email: String(body?.email ?? ''),
      password: String(body?.password ?? ''),
      fullName: String(body?.fullName ?? ''),
      phone: String(body?.phone ?? ''),
      acceptedServiceTerms: body?.acceptedServiceTerms === true,
      acceptedPersonalData: body?.acceptedPersonalData === true,
      consentSnapshot: body?.consentSnapshot,
      consentEvidence: body?.consentEvidence,
    }, deliveryKey, userAgent, ip);
  }

  @Public()
  @HttpCode(202)
  @RateLimit({ name: 'gekta_register_resend', scope: 'ip', limit: 5, windowSeconds: 300, limitEnv: 'RATE_LIMIT_GEKTA_REGISTER_RESEND', windowEnv: 'RATE_LIMIT_WINDOW_SECONDS' })
  @Post('register/email/resend')
  resendEmail(
    @Body() body: { email?: string },
    @Headers('x-registration-delivery-key') deliveryKey?: string,
    @Headers('user-agent') userAgent?: string,
    @Ip() ip?: string,
  ) {
    return this.registration.resendEmail(
      String(body?.email ?? ''),
      deliveryKey,
      userAgent,
      ip,
    );
  }

  @Public()
  @HttpCode(200)
  @RateLimit({ name: 'gekta_register_verify', scope: 'ip', limit: 10, windowSeconds: 900, limitEnv: 'RATE_LIMIT_GEKTA_REGISTER_VERIFY', windowEnv: 'RATE_LIMIT_WINDOW_SECONDS' })
  @Post('register/email/verify')
  verifyEmail(
    @Body() body: { token?: string },
    @Headers('x-registration-delivery-key') deliveryKey?: string,
    @Headers('user-agent') userAgent?: string,
    @Ip() ip?: string,
  ) {
    return this.registration.verifyEmail(String(body?.token ?? ''), userAgent, ip, deliveryKey);
  }

  @Public()
  @HttpCode(200)
  @RateLimit({ name: 'gekta_mfa_verify', scope: 'ip', limit: 10, windowSeconds: 900, limitEnv: 'RATE_LIMIT_GEKTA_MFA_VERIFY', windowEnv: 'RATE_LIMIT_WINDOW_SECONDS' })
  @Post('mfa/verify')
  verifyMfa(
    @Body() body: { challengeToken?: string; code?: string },
    @Headers('user-agent') userAgent?: string,
    @Ip() ip?: string,
  ) {
    return this.registration.verifyMfa(
      String(body?.challengeToken ?? ''),
      String(body?.code ?? ''),
      userAgent,
      ip,
    );
  }

  @Public()
  @HttpCode(200)
  @RateLimit({ name: 'gekta_login', scope: 'ip', limit: 8, windowSeconds: 60, limitEnv: 'RATE_LIMIT_GEKTA_LOGIN', windowEnv: 'RATE_LIMIT_WINDOW_SECONDS' })
  @Post('login')
  login(
    @Body() body: { email?: string; password?: string },
    @Headers('user-agent') userAgent?: string,
    @Ip() ip?: string,
  ) {
    return this.registration.login(
      String(body?.email ?? ''),
      String(body?.password ?? ''),
      userAgent,
      ip,
    );
  }

  @Public()
  @HttpCode(200)
  @RateLimit({ name: 'gekta_refresh', scope: 'ip', limit: 30, windowSeconds: 60, limitEnv: 'RATE_LIMIT_GEKTA_REFRESH', windowEnv: 'RATE_LIMIT_WINDOW_SECONDS' })
  @Post('refresh')
  refresh(
    @Body() body: { refreshToken?: string },
    @Headers('user-agent') userAgent?: string,
    @Ip() ip?: string,
  ) {
    return this.productSessions.refresh(String(body?.refreshToken ?? ''), userAgent, ip);
  }

  @Public()
  @HttpCode(200)
  @RateLimit({ name: 'gekta_logout', scope: 'ip', limit: 30, windowSeconds: 60, limitEnv: 'RATE_LIMIT_GEKTA_LOGOUT', windowEnv: 'RATE_LIMIT_WINDOW_SECONDS' })
  @Post('logout')
  logout(
    @Body() body: { refreshToken?: string },
    @Headers('user-agent') userAgent?: string,
    @Ip() ip?: string,
  ) {
    return this.productSessions.logout(String(body?.refreshToken ?? ''), userAgent, ip);
  }
}

import { BadRequestException, Injectable, UnauthorizedException } from '@nestjs/common';
import { hashPassword, upgradePasswordHashIfNeeded, verifyPassword } from './password-hashing';
import {
  isStrongPassword,
  MAX_PASSWORD_LENGTH,
  MIN_PASSWORD_LENGTH,
} from '../../common/validators/strong-password.validator';
import { randomUUID } from 'crypto';
import { appendAuthAudit } from './auth-audit';
import { hashAuthMaterial, hashClientValue, secureEqual } from './auth-crypto';
import { isGektaLegalEvidence, verifyGektaConsentSnapshot } from '../../../../../packages/domain-core/src/gekta-consent-evidence';
import { PersistentAuthRepository } from './persistent-auth.repository';
import { ProductSessionService } from './product-session.service';
import {
  REGISTRATION_EMAIL_TTL_MS,
  issueRegistrationEmailToken,
  parseRegistrationEmailToken,
  registrationTokenHashMatches,
} from './registration-token';

/**
 * Регистрация в Гекте.
 *
 * Корпоративная регистрация «Прозрачной Цены» здесь неприменима: она требует
 * ИНН, создаёт организацию и ставит заявку в очередь на проверку. Пользователю
 * Гекты нечего проверять — он покупает доступ себе.
 *
 * Вторая система аккаунтов при этом не создаётся: те же public.users, тот же
 * bcrypt, та же таблица одноразовых токенов подтверждения email, тот же MFA и
 * тот же журнал аудита. Разница ровно одна — у пользователя нет организации,
 * поэтому и сессия у него ограниченная.
 *
 * Шаги: заявка → подтверждение email → обязательный MFA → активная сессия.
 * Пробный период выдаётся не здесь: его выдаёт GektaAccessService при первом
 * обращении к кабинету, один раз на пользователя.
 */

const MAX_EMAIL_LENGTH = 320;
const MAX_NAME_LENGTH = 120;
const MAX_PHONE_LENGTH = 32;
const MAX_FAILED_LOGINS = 5;
const LOGIN_LOCKOUT_MS = 15 * 60 * 1000;
const EMAIL_RESEND_COOLDOWN_MS = 60 * 1000;

export type GektaRegistrationInput = {
  email: string;
  password: string;
  fullName: string;
  phone: string;
  acceptedServiceTerms: boolean;
  acceptedPersonalData: boolean;
  consentSnapshot?: unknown;
  consentEvidence?: unknown;
};

function assertPasswordPolicy(password: string): void {
  // Delegates to the one policy in strong-password.validator.ts. This used to
  // be a private copy, and the copy had already lost the all-same and
  // sequential checks the shared rule applies.
  if (!isStrongPassword(password)) {
    throw new BadRequestException({
      code: 'PASSWORD_POLICY_FAILED',
      message: `Пароль должен быть от ${MIN_PASSWORD_LENGTH} до ${MAX_PASSWORD_LENGTH} символов, содержать минимум три класса символов и не быть простой последовательностью.`,
    });
  }
}

/**
 * Телефон нормализуется, но не проверяется владением: SMS не отправляется, и
 * ни один экран не называет такой номер подтверждённым.
 */
export function normalizeDeclaredPhone(input: string): string {
  const trimmed = String(input ?? '').trim();
  const digits = trimmed.replace(/\D/gu, '');
  if (digits.length < 10 || digits.length > 15 || trimmed.length > MAX_PHONE_LENGTH) {
    throw new BadRequestException({
      code: 'PHONE_REQUIRED',
      message: 'Укажи телефон в международном формате.',
    });
  }
  return trimmed;
}

function deliveryAuthorized(provided?: string): boolean {
  const expected = String(process.env.REGISTRATION_DELIVERY_KEY ?? '').trim();
  const candidate = String(provided ?? '').trim();
  return expected.length >= 32 && candidate.length >= 32 && secureEqual(candidate, expected);
}

@Injectable()
export class GektaRegistrationService {
  constructor(
    private readonly repository: PersistentAuthRepository,
    private readonly productSessions: ProductSessionService,
  ) {}

  /**
   * Заявка на регистрацию.
   *
   * Ответ на занятый email не отличается от ответа на свободный: иначе форма
   * стала бы способом перечислять пользователей платформы. Токен возвращается
   * вызывающему только для доставки письма — он не является сессией и сам по
   * себе не даёт доступа.
   */
  async register(
    input: GektaRegistrationInput,
    deliveryKey?: string,
    userAgent?: string,
    ip?: string,
  ) {
    const email = String(input.email ?? '').trim().toLowerCase();
    const fullName = String(input.fullName ?? '').trim();
    if (email.length < 3 || email.length > MAX_EMAIL_LENGTH || !email.includes('@')) {
      throw new BadRequestException({ code: 'EMAIL_INVALID' });
    }
    if (fullName.length < 2 || fullName.length > MAX_NAME_LENGTH) {
      throw new BadRequestException({ code: 'NAME_REQUIRED' });
    }
    if (!input.acceptedServiceTerms || !input.acceptedPersonalData) {
      // Согласие на обработку персональных данных — отдельный факт, а не
      // галочка внутри пользовательского соглашения.
      throw new BadRequestException({ code: 'CONSENT_REQUIRED' });
    }
    assertPasswordPolicy(String(input.password ?? ''));
    const phone = normalizeDeclaredPhone(input.phone);

    const consentEvidence = input.consentEvidence;
    const consentProof = deliveryAuthorized(deliveryKey)
      ? verifyGektaConsentSnapshot(input.consentSnapshot, consentEvidence, String(deliveryKey).trim()) : null;
    if (!consentProof || !isGektaLegalEvidence(consentEvidence)) {
      throw new BadRequestException({ code: 'CONSENT_REFRESH_REQUIRED' });
    }

    const passwordHash = await hashPassword(input.password);
    const userId = `usr_${randomUUID()}`;
    const emailToken = issueRegistrationEmailToken();
    const now = new Date();

    const result = await this.repository.transaction(async (tx) => {
      const prepared = await this.repository.prepareGektaRegistrationIdentity(tx, {
        userId,
        email,
        phone,
        passwordHash,
        fullName,
      });
      if (!prepared || prepared.outcome !== 'CREATED' || !prepared.user_id) {
        await appendAuthAudit(this.repository, tx, {
          action: 'auth.gekta.register',
          outcome: 'DENIED',
          reason: 'EMAIL_ALREADY_REGISTERED',
          metadata: this.clientMetadata(userAgent, ip, { accountHash: hashAuthMaterial(`account:${email}`) }),
        });
        return { kind: 'suppressed' as const };
      }

      await this.repository.ensureCredentialState(
        tx,
        prepared.user_id,
        `${consentEvidence.terms.version}|${consentEvidence.privacy.version}`,
        now,
      );
      await this.repository.createGektaEmailChallenge(tx, {
        id: emailToken.id,
        userId: prepared.user_id,
        tokenHash: emailToken.hash,
        expiresAt: new Date(now.getTime() + REGISTRATION_EMAIL_TTL_MS),
      });
      await appendAuthAudit(this.repository, tx, {
        userId: prepared.user_id,
        action: 'auth.gekta.register',
        outcome: 'SUCCESS',
        metadata: this.clientMetadata(userAgent, ip, {
          consent: consentEvidence,
          consentPresentation: { evidenceHash: consentProof.evidenceHash,
            issuedAt: new Date(consentProof.issuedAt).toISOString(), acceptedAt: now.toISOString() },
          acceptedServiceTerms: true,
          acceptedPersonalData: true,
          phoneState: 'DECLARED',
        }),
      });
      return { kind: 'created' as const, userId: prepared.user_id };
    });

    // Форма отвечает одинаково в обоих случаях. Письмо уходит только на
    // действительно созданный аккаунт.
    return {
      status: 'EMAIL_VERIFICATION_REQUIRED' as const,
      email,
      expiresInSeconds: Math.floor(REGISTRATION_EMAIL_TTL_MS / 1000),
      ...(result.kind === 'created' && deliveryAuthorized(deliveryKey)
        ? { emailDelivery: { email, token: emailToken.token } }
        : {}),
    };
  }

  /**
   * Повторная доставка подтверждения email.
   *
   * Публичный ответ одинаков для неизвестного, уже занятого и ожидающего
   * подтверждения адреса. Сам одноразовый bearer-токен возвращается только
   * доверенному web-BFF, доказавшему внутренний delivery key.
   */
  async resendEmail(
    emailInput: string,
    deliveryKey?: string,
    userAgent?: string,
    ip?: string,
  ) {
    const email = String(emailInput ?? '').trim().toLowerCase();
    if (email.length < 3 || email.length > MAX_EMAIL_LENGTH || !email.includes('@')) {
      throw new BadRequestException({ code: 'EMAIL_INVALID' });
    }

    const emailToken = issueRegistrationEmailToken();
    const now = new Date();
    const result = await this.repository.transaction(async (tx) => {
      await this.repository.lockGektaRegistrationEmail(tx, email);
      const credential = await this.repository.findGektaLoginCredential(tx, email);
      if (!credential || credential.user_status !== 'PENDING_EMAIL_VERIFICATION') {
        await appendAuthAudit(this.repository, tx, {
          action: 'auth.gekta.email_resend',
          outcome: 'SUCCESS',
          reason: 'PUBLIC_REQUEST_ACCEPTED',
          metadata: this.clientMetadata(userAgent, ip, {
            accountHash: hashAuthMaterial(`account:${email}`),
          }),
        });
        return { kind: 'suppressed' as const };
      }

      const latest = await this.repository.getLatestGektaEmailChallengeForUpdate(
        tx,
        credential.user_id,
      );
      if (latest && now.getTime() - latest.created_at.getTime() < EMAIL_RESEND_COOLDOWN_MS) {
        return { kind: 'cooldown' as const };
      }

      await this.repository.revokePendingGektaEmailChallenges(tx, credential.user_id);
      await this.repository.createGektaEmailChallenge(tx, {
        id: emailToken.id,
        userId: credential.user_id,
        tokenHash: emailToken.hash,
        expiresAt: new Date(now.getTime() + REGISTRATION_EMAIL_TTL_MS),
      });
      await appendAuthAudit(this.repository, tx, {
        userId: credential.user_id,
        action: 'auth.gekta.email_resend',
        outcome: 'SUCCESS',
        reason: 'EMAIL_VERIFICATION_RESENT',
        metadata: this.clientMetadata(userAgent, ip),
      });
      return { kind: 'created' as const };
    });

    return {
      accepted: true as const,
      cooldownSeconds: Math.floor(EMAIL_RESEND_COOLDOWN_MS / 1000),
      ...(result.kind === 'created' && deliveryAuthorized(deliveryKey)
        ? { emailDelivery: { email, token: emailToken.token } }
        : {}),
    };
  }

  /**
   * Подтверждение email.
   *
   * Токен потребляется один раз, пользователь становится ACTIVE, и тут же
   * создаётся сессия, ожидающая MFA. Активных токенов до прохождения MFA не
   * выдаётся ни одного.
   */
  async verifyEmail(tokenInput: string, userAgent?: string, ip?: string, deliveryKey?: string) {
    const parsed = parseRegistrationEmailToken(tokenInput);
    if (!parsed) throw new BadRequestException({ code: 'REGISTRATION_EMAIL_TOKEN_INVALID' });
    const now = new Date();

    const result = await this.repository.transaction(async (tx) => {
      const challenge = await this.repository.getGektaEmailChallengeForUpdate(tx, parsed.id);
      if (
        !challenge
        || challenge.status !== 'PENDING'
        || challenge.expires_at <= now
        || !registrationTokenHashMatches(challenge.token_hash, parsed.hash)
      ) {
        return { kind: 'invalid' as const };
      }

      const consumed = await this.repository.consumeGektaEmailChallenge(tx, challenge.id, now);
      if (consumed !== 1) return { kind: 'invalid' as const };

      const verified = await this.repository.markGektaEmailVerified(tx, challenge.id, challenge.user_id);
      if (!verified) return { kind: 'invalid' as const };

      const credential = await this.repository.getCredentialState(tx, challenge.user_id, true);
      if (!credential) return { kind: 'invalid' as const };

      const identity = await this.repository.getProductRegistrationSubject(tx, challenge.user_id);
      if (!identity) return { kind: 'invalid' as const };

      const enrollment = await this.productSessions.issueMfaSession(tx, {
        userId: challenge.user_id,
        email: identity.email,
        credentialVersion: credential.credential_version,
        enrollment: true,
        userAgent,
        ip,
      });
      await appendAuthAudit(this.repository, tx, {
        userId: challenge.user_id,
        sessionId: enrollment.sessionId,
        action: 'auth.gekta.email_verified',
        outcome: 'SUCCESS',
        metadata: this.clientMetadata(userAgent, ip),
      });
      return {
        kind: 'verified' as const,
        enrollment,
        email: identity.email,
        declaredPhone: identity.phone,
      };
    });

    if (result.kind === 'invalid') throw new BadRequestException({ code: 'REGISTRATION_EMAIL_TOKEN_INVALID' });
    return {
      status: 'MFA_ENROLLMENT_REQUIRED' as const,
      challengeToken: result.enrollment.challengeToken,
      expiresAt: result.enrollment.expiresAt,
      setupSecret: result.enrollment.setupSecret,
      otpAuthUri: result.enrollment.otpAuthUri,
      ...(deliveryAuthorized(deliveryKey) && result.declaredPhone
        ? { email: result.email, declaredPhone: result.declaredPhone }
        : {}),
    };
  }

  /** Завершение регистрации: проверка кода MFA и выдача активной сессии. */
  async verifyMfa(challengeToken: string, code: string, userAgent?: string, ip?: string) {
    const activated = await this.productSessions.verifyMfa(challengeToken, code, userAgent, ip);
    return {
      status: 'ACTIVE' as const,
      accessToken: activated.accessToken,
      refreshToken: activated.refreshToken,
      backupCodes: activated.backupCodes,
      user: activated.user,
    };
  }

  /**
   * Повторный вход пользователя Гекты.
   *
   * Тот же порядок, что у платформы: сначала доказательство пароля, и только
   * потом любое состояние аккаунта. Ответ на несуществующий email не
   * отличается от ответа на неверный пароль.
   */
  async login(emailInput: string, password: string, userAgent?: string, ip?: string) {
    const email = String(emailInput ?? '').trim().toLowerCase();
    const accountHash = hashAuthMaterial(`account:${email}`);
    const credential = await this.repository.findGektaLoginCredential(this.repository.prisma, email);
    // Same opportunistic upgrade as the platform pathway, from the same
    // function. Two login paths with two different rehash rules would leave one
    // population truncated at 72 bytes forever.
    const validPassword = await verifyPassword(String(password ?? ''), credential?.password_hash);
    const result = await this.repository.transaction(async (tx) => {
      await this.repository.ensureLoginThrottle(tx, accountHash);
      const throttle = await this.repository.getLoginThrottle(tx, accountHash, true);
      const now = new Date();
      if (throttle?.locked_until && throttle.locked_until > now) {
        await appendAuthAudit(this.repository, tx, {
          userId: credential?.user_id,
          action: 'auth.gekta.login',
          outcome: 'DENIED',
          reason: 'ACCOUNT_TEMPORARILY_LOCKED',
          metadata: this.clientMetadata(userAgent, ip, { accountHash }),
        });
        return { kind: 'invalid' as const };
      }

      if (!credential || !validPassword || credential.user_status !== 'ACTIVE') {
        const failures = (throttle?.failures ?? 0) + 1;
        const lockedUntil = failures >= MAX_FAILED_LOGINS
          ? new Date(now.getTime() + LOGIN_LOCKOUT_MS)
          : null;
        await this.repository.setLoginThrottle(
          tx,
          accountHash,
          lockedUntil ? 0 : failures,
          lockedUntil,
        );
        await appendAuthAudit(this.repository, tx, {
          userId: credential?.user_id,
          action: 'auth.gekta.login',
          outcome: 'FAILURE',
          reason: 'INVALID_CREDENTIALS',
          metadata: this.clientMetadata(userAgent, ip, {
            accountHash,
            locked: Boolean(lockedUntil),
          }),
        });
        return { kind: 'invalid' as const };
      }

      // Пароль перечитывается в той же сериализуемой транзакции: смена пароля
      // между bcrypt и выдачей сессии обесценивает доказательство.
      const current = await this.repository.findGektaLoginCredential(tx, email);
      if (
        !current
        || current.user_id !== credential.user_id
        || !secureEqual(current.password_hash, credential.password_hash)
      ) {
        return { kind: 'invalid' as const };
      }
      const state = await this.repository.getCredentialState(tx, current.user_id, true);
      if (!state) return { kind: 'invalid' as const };
      const identity = await this.repository.getProductRegistrationSubject(tx, current.user_id);
      if (!identity) return { kind: 'invalid' as const };

      // MFA у Гекты обязателен, поэтому вход всегда идёт через проверку кода:
      // активных токенов на этом шаге не выдаётся.
      const enrollment = await this.productSessions.issueMfaSession(tx, {
        userId: current.user_id,
        email: identity.email,
        credentialVersion: state.credential_version,
        // Once MFA has been enabled, password login may only verify the
        // existing factor (TOTP or a one-time backup code). Missing/corrupt
        // ciphertext is not permission to silently replace that factor.
        enrollment: !state.mfa_enabled,
        userAgent,
        ip,
      });
      await this.repository.clearLoginThrottle(tx, accountHash);
      await this.repository.markLoginSuccess(tx, current.user_id);
      await appendAuthAudit(this.repository, tx, {
        userId: current.user_id,
        sessionId: enrollment.sessionId,
        action: 'auth.gekta.login',
        outcome: 'SUCCESS',
        metadata: this.clientMetadata(userAgent, ip),
      });
      return { kind: 'mfa' as const, enrollment };
    });

    // Перезапись legacy-хеша — после решения о входе и только при успехе.
    // Между доказательством пароля и перечитыванием в транзакции её быть не
    // может: перечитывание для того и существует, чтобы отказать, если хеш
    // изменился, а перезапись — это ровно такое изменение. Так первый же вход
    // каждой учётной записи с bcrypt-хешем и получал отказ.
    if (credential && validPassword && result.kind !== 'invalid') {
      await upgradePasswordHashIfNeeded(
        String(password ?? ''),
        credential.password_hash,
        (next, conditionalOn) => this.repository.upgradePasswordHashFormat(
          this.repository.prisma,
          credential.user_id,
          next,
          conditionalOn,
        ),
      );
    }

    if (result.kind === 'invalid') throw new UnauthorizedException({ code: 'INVALID_CREDENTIALS' });
    return {
      status: 'MFA_REQUIRED' as const,
      challengeToken: result.enrollment.challengeToken,
      expiresAt: result.enrollment.expiresAt,
      setupSecret: result.enrollment.setupSecret,
      otpAuthUri: result.enrollment.otpAuthUri,
    };
  }

  private clientMetadata(
    userAgent?: string,
    ip?: string,
    extra: Record<string, unknown> = {},
  ): Record<string, unknown> {
    return {
      userAgentHash: hashClientValue(userAgent),
      ipHash: hashClientValue(ip),
      ...extra,
    };
  }
}

