const ANONYMOUS_TEST_KEY = fixtureValue('anonymous');

function setEnv(name: string, value: string | undefined) {
  if (value === undefined) delete process.env[name];
  else process.env[name] = value;
}

function bffRequest(body: Record<string, unknown>): Request {
  const locale = body.locale === 'en' || body.locale === 'zh' ? body.locale : 'ru';
  body = { consentSnapshot: registrationConsentPresentation(locale, DELIVERY_KEY).snapshot, ...body };
  return {
    method: 'POST',
    url: 'https://gekta.example.test/api/gekta/auth/register',
    headers: new Headers({
      cookie: 'pc_csrf_token=csrf-test',
      'x-csrf-token': 'csrf-test',
      'content-type': 'application/json',
    }),
    text: async () => JSON.stringify(body),
  } as unknown as Request;
}

function chatRequest(input: { ticket?: string; cookie?: string }): NextRequest {
  const url = 'https://example.test/api/agro-chat?stream=1';
  return {
    url,
    nextUrl: new URL(url),
    headers: new Headers({
      'content-type': 'application/json',
      'sec-fetch-site': 'same-origin',
      ...(input.ticket ? { 'x-gekta-answer-ticket': input.ticket } : {}),
      ...(input.cookie ? { cookie: input.cookie } : {}),
    }),
    cookies: {
      get: (name: string) => name === GEKTA_ANONYMOUS_COOKIE && input.cookie
        ? { name, value: input.cookie.slice(input.cookie.indexOf('=') + 1) }
        : undefined,
    },
    signal: new AbortController().signal,
    text: async () => JSON.stringify({
      message: 'Посев озимой пшеницы', locale: 'ru', context: 'gekta-standalone', history: [],
    }),
  } as unknown as NextRequest;
}

describe('Gekta registration security boundary', () => {
  const original = {
    api: process.env.API_URL,
    delivery: process.env.REGISTRATION_DELIVERY_KEY,
    resendKey: process.env.RESEND_API_KEY,
    resendFrom: process.env.RESEND_FROM_EMAIL,
    origin: process.env.PC_PUBLIC_ORIGIN,
    mfa: process.env.MFA_LOGIN_TICKET_SECRET,
    anonymous: process.env.GEKTA_ANONYMOUS_SESSION_SECRET,
  };

  beforeEach(() => {
    process.env.API_URL = 'https://api.example.test';
    process.env.REGISTRATION_DELIVERY_KEY = DELIVERY_KEY;
    process.env.RESEND_API_KEY = fixtureValue('resend');
    process.env.RESEND_FROM_EMAIL = 'Gekta <no-reply@example.test>';
    process.env.PC_PUBLIC_ORIGIN = 'https://gekta.example.test';
    process.env.MFA_LOGIN_TICKET_SECRET = MFA_TEST_KEY;
    process.env.GEKTA_ANONYMOUS_SESSION_SECRET = ANONYMOUS_TEST_KEY;
  });

  afterEach(() => {
    setEnv('API_URL', original.api);
    setEnv('REGISTRATION_DELIVERY_KEY', original.delivery);
    setEnv('RESEND_API_KEY', original.resendKey);
    setEnv('RESEND_FROM_EMAIL', original.resendFrom);
    setEnv('PC_PUBLIC_ORIGIN', original.origin);
    setEnv('MFA_LOGIN_TICKET_SECRET', original.mfa);
    setEnv('GEKTA_ANONYMOUS_SESSION_SECRET', original.anonymous);
    vi.unstubAllGlobals();
  });

  it('preserves an upstream consent-refresh rejection after local proof validation', async () => {
    const fetch = vi.fn(async () => Response.json({ code: 'CONSENT_REFRESH_REQUIRED', privateDetail: 'not-public' }, { status: 400 }));
    vi.stubGlobal('fetch', fetch);
    const response = await registerPost(bffRequest({ fullName: 'Тест согласия', phone: '+7 916 000-00-00',
      email: 'consent-boundary@example.test', password: fixtureValue('Strong1!'), acceptedServiceTerms: true,
      acceptedPersonalData: true, locale: 'ru' }));
    expect(response.status).toBe(400);
    const payload = await response.json();
    expect(payload.code).toBe('CONSENT_REFRESH_REQUIRED');
    expect(payload.privateDetail).toBeUndefined();
    expect(fetch).toHaveBeenCalledTimes(1);
  });

  it('keeps unknown upstream registration codes private', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => Response.json({ code: 'PRIVATE_DIAGNOSTIC', privateDetail: 'not-public' }, { status: 400 })));
    const response = await registerPost(bffRequest({ fullName: 'Тест согласия', phone: '+7 916 000-00-00',
      email: 'consent-boundary@example.test', password: fixtureValue('Strong1!'), acceptedServiceTerms: true,
      acceptedPersonalData: true, locale: 'ru' }));
    expect(response.status).toBe(400);
    const payload = await response.json();
    expect(payload.code).toBe('REGISTRATION_REQUEST_INVALID');
    expect(payload.privateDetail).toBeUndefined();
  });

  it('keeps the API email bearer token inside the BFF while sending the real link', async () => {
    const calls: Array<{ url: string; init?: RequestInit }> = [];
    vi.stubGlobal('fetch', vi.fn(async (input: string | URL | Request, init?: RequestInit) => {
      const url = String(input);
      calls.push({ url, init });
      if (url.endsWith('/gekta/auth/register')) {
        return Response.json({
          status: 'EMAIL_VERIFICATION_REQUIRED',
          emailDelivery: { email: 'new@example.test', token: 'rev_secret_bearer_token' },
        });
      }
      if (url === 'https://api.resend.com/emails') return Response.json({ id: 'mail-1' });
      return new Response(null, { status: 500 });
    }));

    const response = await registerPost(bffRequest({
        fullName: 'Иван Агроном',
        phone: '+7 916 000-00-00',
        email: 'new@example.test',
        password: 'Sever0oborot!2026',
        acceptedServiceTerms: true,
        acceptedPersonalData: true,
        locale: 'ru',
    }));

    expect(response.status).toBe(202);
    expect(await response.text()).not.toContain('rev_secret_bearer_token');
    expect(new Headers(calls[0].init?.headers).get('x-registration-delivery-key')).toBe(DELIVERY_KEY);
    const forwarded = JSON.parse(String(calls[0].init?.body));
    expect(forwarded.consentEvidence).toEqual(currentGektaLegalEvidence('ru', 'GEKTA_REGISTRATION'));
    expect(String(calls[1].init?.body)).toContain('https://gekta.example.test/api/gekta/auth/email/verify?token=rev_secret_bearer_token');
  });

  it('returns the same accepted response when the API suppresses an existing email', async () => {
    const fetchMock = vi.fn(async () => Response.json({ status: 'EMAIL_VERIFICATION_REQUIRED' }));
    vi.stubGlobal('fetch', fetchMock);
    const response = await registerPost(bffRequest({
        fullName: 'Иван Агроном', phone: '+7 916 000-00-00', email: 'used@example.test',
        password: 'Sever0oborot!2026', acceptedServiceTerms: true, acceptedPersonalData: true,
    }));
    expect(response.status).toBe(202);
    expect(await response.json()).toMatchObject({ accepted: true, status: 'EMAIL_VERIFICATION_REQUIRED' });
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it.each(['missing', 'tampered', 'expired', 'locale changed', 'operator changed'])(
    'rejects a %s displayed-document commitment before API/mail side effects', async (variant) => {
      const fetchMock = vi.fn();
      vi.stubGlobal('fetch', fetchMock);
      const evidence = currentGektaLegalEvidence('ru', 'GEKTA_REGISTRATION');
      const body: Record<string, unknown> = { fullName: 'Иван Агроном', phone: '+7 916 000-00-00', email: 'new@example.test',
        password: 'Sever0oborot!2026', acceptedServiceTerms: true, acceptedPersonalData: true, locale: 'ru',
        consentSnapshot: sealGektaConsentSnapshot(evidence, DELIVERY_KEY) };
      if (variant === 'missing') body.consentSnapshot = undefined;
      if (variant === 'tampered') body.consentSnapshot = `${body.consentSnapshot}x`;
      if (variant === 'expired') body.consentSnapshot = sealGektaConsentSnapshot(evidence, DELIVERY_KEY, new Date(Date.now() - 16 * 60_000));
      if (variant === 'locale changed') body.locale = 'en';
      const previousProfile = process.env.GEKTA_MERCHANT_PROFILE_ID;
      const previousName = process.env.GEKTA_MERCHANT_LEGAL_NAME;
      try {
        if (variant === 'operator changed') { process.env.GEKTA_MERCHANT_PROFILE_ID = 'changed-profile'; process.env.GEKTA_MERCHANT_LEGAL_NAME = 'Test changed operator'; }
        const response = await registerPost(bffRequest(body));
        expect(response.status).toBe(400);
        expect(await response.json()).toMatchObject({ code: 'CONSENT_REFRESH_REQUIRED' });
        expect(fetchMock).not.toHaveBeenCalled();
      } finally { setEnv('GEKTA_MERCHANT_PROFILE_ID', previousProfile); setEnv('GEKTA_MERCHANT_LEGAL_NAME', previousName); }
    },
  );

  it('ignores a forged client legal receipt and forwards only the server-rendered documents', async () => {
    const fetchMock = vi.fn(async () => Response.json({ status: 'EMAIL_VERIFICATION_REQUIRED' }));
    vi.stubGlobal('fetch', fetchMock);
    const response = await registerPost(bffRequest({ fullName: 'Иван Агроном', phone: '+7 916 000-00-00', email: 'new@example.test',
      password: 'Sever0oborot!2026', acceptedServiceTerms: true, acceptedPersonalData: true, locale: 'en',
      consentEvidence: { terms: { source: '/platform-v7/terms', version: 'fake' } } }));
    expect(response.status).toBe(202);
    const sent = JSON.parse(String(fetchMock.mock.calls[0]?.[1]?.body));
    expect(sent.consentEvidence).toEqual(currentGektaLegalEvidence('en', 'GEKTA_REGISTRATION'));
  });

  it('rejects an oversized auth body before calling the API', async () => {
    const fetchMock = vi.fn();
    vi.stubGlobal('fetch', fetchMock);
    const response = await registerPost({
      method: 'POST',
      url: 'https://gekta.example.test/api/gekta/auth/register',
      headers: new Headers({
        cookie: 'pc_csrf_token=csrf-test',
        'x-csrf-token': 'csrf-test',
        'content-length': String(17 * 1_024),
      }),
      text: async () => JSON.stringify({ email: 'new@example.test' }),
    } as unknown as Request);
    expect(response.status).toBe(400);
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it('derives rate-limit identity only from Caddy\'s nearest forwarded hop', () => {
    const headers = new Headers({
      'x-nf-client-connection-ip': '198.51.100.20',
      'cf-connecting-ip': '198.51.100.21',
      'x-real-ip': '198.51.100.22',
      'x-forwarded-for': '198.51.100.23, 203.0.113.7',
    });
    expect(trustedRequestIp({ headers } as Request)).toBe('203.0.113.7');
    expect(trustedRequestIp({ headers: new Headers({ 'cf-connecting-ip': '198.51.100.21' }) } as Request)).toBe('');
    expect(trustedRequestIp({ headers: new Headers({ 'x-forwarded-for': '198.51.100.23, forged' }) } as Request)).toBe('');
  });

  it('does not claim that a verification email was sent when delivery failed', async () => {
    vi.stubGlobal('fetch', vi.fn(async (input: string | URL | Request) => {
      const url = String(input);
      if (url.endsWith('/gekta/auth/register')) {
        return Response.json({
          status: 'EMAIL_VERIFICATION_REQUIRED',
          emailDelivery: { email: 'new@example.test', token: 'rev_secret_bearer_token' },
        });
      }
      if (url === 'https://api.resend.com/emails') return new Response('unavailable', { status: 503 });
      return new Response(null, { status: 500 });
    }));
    const response = await registerPost(bffRequest({
      fullName: 'Иван Агроном', phone: '+7 916 000-00-00', email: 'new@example.test',
      password: 'Sever0oborot!2026', acceptedServiceTerms: true, acceptedPersonalData: true,
    }));
    expect(response.status).toBe(503);
    expect(await response.json()).toMatchObject({ code: 'REGISTRATION_EMAIL_DELIVERY_UNAVAILABLE' });
  });

  it('encrypts the pending challenge and declared phone in a short-lived strict cookie', () => {
    const ticket = sealGektaMfaTicket({
      challengeToken: 'mc_challenge-token-at-least-16',
      email: 'new@example.test',
      enrollment: true,
      setupSecret: 'TOTPSECRET',
      otpAuthUri: 'otpauth://totp/Gekta:new@example.test?secret=TOTPSECRET',
      declaredPhone: '+7 916 000-00-00',
    }, 1_000);
    expect(ticket).not.toContain('mc_challenge');
    expect(ticket).not.toContain('+7 916');
    expect(openGektaMfaTicket(ticket, 1_001)).toMatchObject({
      challengeToken: 'mc_challenge-token-at-least-16',
      declaredPhone: '+7 916 000-00-00',
    });
    expect(openGektaMfaTicket(ticket, 1_601)).toBeNull();
    expect(openGektaMfaTicket(`${ticket.slice(0, -1)}x`, 1_001)).toBeNull();
    expect(gektaMfaCookieOptions()).toMatchObject({ httpOnly: true, sameSite: 'strict', path: '/api/gekta/auth' });
    expect(clearGektaMfaCookieOptions().maxAge).toBe(0);
    expect(() => sealGektaMfaTicket({
      challengeToken: 'mc_challenge-token-at-least-16',
      email: 'new@example.test',
      enrollment: true,
      setupSecret: 'TOTPSECRET',
    })).toThrow('Invalid Gekta MFA ticket input');
  });

  it('turns the email bearer into a purpose-bound HttpOnly ticket without consuming it on GET', async () => {
    const raw = 'rev_email-bearer-token-at-least-32-characters';
    const sealed = sealGektaEmailTicket(raw, 1_000);
    expect(sealed).not.toContain(raw);
    expect(openGektaEmailTicket(sealed, 1_001)).toBe(raw);
    expect(openGektaEmailTicket(sealed, 2_801)).toBeNull();
    expect(gektaEmailCookieOptions()).toMatchObject({
      httpOnly: true,
      sameSite: 'strict',
      path: '/api/gekta/auth/email/verify',
    });

    const response = verificationGet(new Request(`https://gekta.example.test/api/gekta/auth/email/verify?token=${raw}&lang=en`));
    expect(response.status).toBe(303);
    expect(response.headers.get('location')).toBe('https://gekta.example.test/gekta/register?lang=en&confirm=email');
    expect(response.headers.get('location')).not.toContain(raw);
    expect(response.headers.get('set-cookie')).not.toContain(raw);
    expect(response.headers.get('referrer-policy')).toBe('no-referrer');
  });

  it('requires an explicit browser POST and never exposes bearer challenges to client code', () => {
    const client = read('components/gekta/GektaRegistrationClient.tsx');
    const verifyRoute = read('app/api/gekta/auth/email/verify/route.ts');
    expect(client).not.toContain("params.get('verify')");
    expect(client).toContain("step === 'verify'");
    expect(client).toContain("post('/api/gekta/auth/email/verify', {})");
    expect(verifyRoute).toContain('export function GET(request: Request)');
    expect(verifyRoute).toContain('openGektaEmailTicket');
    expect(verifyRoute).toContain('sealGektaMfaTicket');
    expect(verifyRoute).not.toMatch(/challengeToken:\s*payload\.challengeToken[,\s]*\n\s*correlationId/u);
  });
});

describe('Gekta answer admission', () => {
  beforeEach(() => {
    process.env.API_URL = 'https://api.example.test';
    process.env.REGISTRATION_DELIVERY_KEY = DELIVERY_KEY;
    process.env.GEKTA_ANONYMOUS_SESSION_SECRET = ANONYMOUS_TEST_KEY;
    delete process.env.TAI_RESTRICTED_QWEN_PUBLIC_ENABLED;
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it('rejects a direct standalone generation that has no server reservation', async () => {
    const response = await chatPost(chatRequest({}));
    expect(response.status).toBe(401);
    expect(await response.json()).toEqual({ code: 'GEKTA_ANSWER_RESERVATION_REQUIRED' });
  });

  it('consumes the matching signed reservation at generation admission', async () => {
    const ticket = issueTicket();
    const now = new Date();
    const reserved = reserveAnswer(recordConsent(createAnonymousSession(now), GEKTA_LEGAL_VERSION, now), ticket);
    const serialized = serializeAnonymousSession(reserved);
    expect(parseAnonymousSession(serialized)).toMatchObject({ pending: ticket });
    vi.stubGlobal('fetch', vi.fn(async (input: string | URL | Request) => {
      expect(String(input)).toBe('https://api.example.test/gekta/internal/anonymous-answer/admit');
      return new Response(JSON.stringify({ allowed: true }), { status: 200 });
    }));
    const response = await chatPost(chatRequest({
      ticket,
      cookie: `${GEKTA_ANONYMOUS_COOKIE}=${serialized}`,
    }));
    expect(response.status).toBe(200);
    const rawCookie = /gekta_anon=([^;]+)/u.exec(response.headers.get('set-cookie') || '')?.[1] || '';
    expect(parseAnonymousSession(decodeURIComponent(rawCookie))).toMatchObject({ used: 1, pending: null });
  });

  it('rejects a replay even when the browser resends its old signed cookie', async () => {
    const ticket = issueTicket();
    const now = new Date();
    const serialized = serializeAnonymousSession(reserveAnswer(recordConsent(createAnonymousSession(now), GEKTA_LEGAL_VERSION, now), ticket));
    const durable = vi.fn()
      .mockResolvedValueOnce(new Response(JSON.stringify({ allowed: true }), { status: 200 }))
      .mockResolvedValueOnce(new Response(JSON.stringify({ allowed: false }), { status: 200 }));
    vi.stubGlobal('fetch', durable);

    const input = { ticket, cookie: `${GEKTA_ANONYMOUS_COOKIE}=${serialized}` };
    expect((await chatPost(chatRequest(input))).status).toBe(200);
    const replay = await chatPost(chatRequest(input));
    expect(replay.status).toBe(409);
    expect(await replay.json()).toEqual({ code: 'GEKTA_ANSWER_RESERVATION_INVALID' });
    expect(durable).toHaveBeenCalledTimes(2);
  });

  it('fails closed when distributed admission is unavailable', async () => {
    const ticket = issueTicket();
    const now = new Date();
    const serialized = serializeAnonymousSession(reserveAnswer(recordConsent(createAnonymousSession(now), GEKTA_LEGAL_VERSION, now), ticket));
    vi.stubGlobal('fetch', vi.fn(async () => new Response(null, { status: 503 })));

    const response = await chatPost(chatRequest({
      ticket,
      cookie: `${GEKTA_ANONYMOUS_COOKIE}=${serialized}`,
    }));
    expect(response.status).toBe(503);
    expect(await response.json()).toEqual({ code: 'GEKTA_SERVICE_UNAVAILABLE' });
  });

  it.each(['absent', 'obsolete', 'withdrawn', 'future', 'before-session', 'fractional'] as const)(
    'rejects a legacy ticket with %s consent before any upstream request', async (kind) => {
      const now = new Date();
      const ticket = issueTicket(now);
      const initial = createAnonymousSession(now);
      const consent = kind === 'absent' ? undefined : kind === 'withdrawn' ? null : {
        version: kind === 'obsolete' ? 'obsolete-version' : GEKTA_LEGAL_VERSION,
        at: kind === 'future' ? now.getTime() + 60_000 : kind === 'before-session' ? now.getTime() - 1 : kind === 'fractional' ? now.getTime() - 0.5 : now.getTime(),
      };
      const serialized = serializeAnonymousSession({ ...reserveAnswer(initial, ticket), consent });
      const upstream = vi.fn(async () => new Response(JSON.stringify({ allowed: true }), { status: 200 }));
      vi.stubGlobal('fetch', upstream);
      const response = await chatPost(chatRequest({ ticket, cookie: `${GEKTA_ANONYMOUS_COOKIE}=${serialized}` }));
      expect(response.status).toBe(409);
      expect(await response.json()).toEqual({ code: 'GEKTA_ANSWER_RESERVATION_INVALID' });
      expect(upstream).not.toHaveBeenCalled();
      expect(response.headers.get('set-cookie')).toBeNull();
    },
  );
});

import { afterEach, describe, expect, it } from 'vitest';
import { renderToStaticMarkup } from 'react-dom/server';
import { currentGektaLegalEvidence, committedGektaDocumentHref, registrationConsentPresentation } from '@/lib/gekta/consent-evidence-server';
import { GEKTA_LEGAL_VERSION, getGektaLegalDocument, renderLegalDocument } from '@/lib/gekta/legal';
import { getMerchantProfile } from '@/lib/gekta/merchant';
import GektaLegalDocumentPage from '@/app/legal/[slug]/page';
import GektaRegisterPage from '@/app/gekta/register/page';
import { GEKTA_CONSENT_SNAPSHOT_TTL_MS, canonicalLegalJson, isGektaLegalEvidence, legalContentHash,
  renderedLegalDocumentHash, sealGektaConsentSnapshot, verifyGektaConsentSnapshot } from '../../../../packages/domain-core/src/gekta-consent-evidence';

const TEST_KEY = 'gekta-public-document-commitment-fixture-32-chars';
const now = new Date('2026-10-08T00:00:00.000Z');
const original = { name: process.env.GEKTA_MERCHANT_LEGAL_NAME, profile: process.env.GEKTA_MERCHANT_PROFILE_ID,
  deliveryKey: process.env.REGISTRATION_DELIVERY_KEY };
afterEach(() => {
  for (const [key, value] of Object.entries({ GEKTA_MERCHANT_LEGAL_NAME: original.name,
    GEKTA_MERCHANT_PROFILE_ID: original.profile, REGISTRATION_DELIVERY_KEY: original.deliveryKey })) {
    if (value === undefined) delete process.env[key]; else process.env[key] = value;
  }
});

describe('Gekta displayed legal evidence', () => {
  it.each(['ru', 'en', 'zh'] as const)('binds the actual rendered Russian documents and %s interface', (locale) => {
    const evidence = currentGektaLegalEvidence(locale, 'GEKTA_REGISTRATION');
    const profile = getMerchantProfile();
    expect(isGektaLegalEvidence(evidence)).toBe(true);
    expect(evidence).toMatchObject({ version: GEKTA_LEGAL_VERSION, surfaceLocale: locale, documentLocale: 'ru',
      profile: { id: profile.id, effectiveFrom: profile.effectiveFrom, contentHash: legalContentHash(profile) } });
    for (const kind of ['terms', 'privacy'] as const) {
      const expected = renderLegalDocument(getGektaLegalDocument(evidence[kind].document.slug)!, profile);
      expect(evidence[kind].document).toEqual(expected);
      expect(evidence[kind].contentHash).toBe(renderedLegalDocumentHash(GEKTA_LEGAL_VERSION, legalContentHash(profile), expected));
      expect(evidence[kind].source).not.toContain('/platform-v7/');
      if (kind === 'terms') expect(expected.sections.at(-1)?.heading).toBe('Исполнитель');
    }
    const token = sealGektaConsentSnapshot(evidence, TEST_KEY, now);
    expect(verifyGektaConsentSnapshot(token, evidence, TEST_KEY, now)).toEqual({ issuedAt: now.getTime(), evidenceHash: legalContentHash(evidence) });
  });

  it('keeps separate registration purposes distinct from the combined anonymous notice', () => {
    const anonymous = currentGektaLegalEvidence('ru', 'GEKTA_ANONYMOUS_NOTICE');
    expect(isGektaLegalEvidence(anonymous)).toBe(true);
    expect(anonymous.terms.purpose).toBe('TERMS_NOTICE');
    expect(anonymous.privacy.purpose).toBe('PRIVACY_NOTICE');
    expect(sealGektaConsentSnapshot(anonymous, TEST_KEY, now)).toBeNull();
  });

  it('is stable for object-key order, sensitive to document order/content and operator profile', () => {
    expect(canonicalLegalJson({ z: 1, a: { b: 2, a: 3 } })).toBe(canonicalLegalJson({ a: { a: 3, b: 2 }, z: 1 }));
    const first = currentGektaLegalEvidence('ru', 'GEKTA_REGISTRATION');
    process.env.GEKTA_MERCHANT_LEGAL_NAME = 'Test operator';
    process.env.GEKTA_MERCHANT_PROFILE_ID = 'new-operator-profile';
    const changed = currentGektaLegalEvidence('ru', 'GEKTA_REGISTRATION');
    expect(changed.profile.contentHash).not.toBe(first.profile.contentHash);
    expect(changed.terms.contentHash).not.toBe(first.terms.contentHash);
    const token = sealGektaConsentSnapshot(first, TEST_KEY, now);
    expect(verifyGektaConsentSnapshot(token, changed, TEST_KEY, now)).toBeNull();
    expect(legalContentHash(['a', 'b'])).not.toBe(legalContentHash(['b', 'a']));
  });

  it('rejects signature/key/locale/content changes, future/expired/invalid clocks and malformed inputs', () => {
    const evidence = currentGektaLegalEvidence('ru', 'GEKTA_REGISTRATION');
    const token = sealGektaConsentSnapshot(evidence, TEST_KEY, now)!;
    expect(verifyGektaConsentSnapshot(`${token}x`, evidence, TEST_KEY, now)).toBeNull();
    expect(verifyGektaConsentSnapshot(token, evidence, `${TEST_KEY}x`, now)).toBeNull();
    expect(verifyGektaConsentSnapshot(token, { ...evidence, surfaceLocale: 'zh' }, TEST_KEY, now)).toBeNull();
    expect(verifyGektaConsentSnapshot(token, evidence, TEST_KEY, new Date(now.getTime() - 1))).toBeNull();
    expect(verifyGektaConsentSnapshot(token, evidence, TEST_KEY, new Date(now.getTime() + GEKTA_CONSENT_SNAPSHOT_TTL_MS))).toBeNull();
    expect(verifyGektaConsentSnapshot(token, evidence, TEST_KEY, new Date(NaN))).toBeNull();
    for (const malformed of [null, [], {}, { ...evidence, extra: 'unsigned' }, { ...evidence, terms: { ...evidence.terms, extra: 'unsigned' } },
      { ...evidence, terms: { ...evidence.terms, document: { ...evidence.terms.document, summary: 'changed' } } }]) {
      expect(isGektaLegalEvidence(malformed)).toBe(false);
      expect(verifyGektaConsentSnapshot(token, malformed, TEST_KEY, now)).toBeNull();
    }
    expect(sealGektaConsentSnapshot(evidence, 'short', now)).toBeNull();
    expect(token).not.toContain(TEST_KEY);
  });

  it('renders the exact committed document and rejects an incomplete/stale commitment link', async () => {
    const evidence = currentGektaLegalEvidence('ru', 'GEKTA_REGISTRATION');
    const href = new URL(committedGektaDocumentHref(evidence, 'terms'), 'https://example.test');
    const params = Promise.resolve({ slug: evidence.terms.document.slug });
    const commitment = Object.fromEntries(href.searchParams.entries());
    const html = renderToStaticMarkup(await GektaLegalDocumentPage({ params, searchParams: Promise.resolve(commitment) }));
    expect(html).toContain('Исполнитель');
    expect(html).toContain(GEKTA_LEGAL_VERSION);
    await expect(GektaLegalDocumentPage({ params, searchParams: Promise.resolve({ ...commitment, h: '0'.repeat(64) }) })).rejects.toThrow();
    await expect(GektaLegalDocumentPage({ params, searchParams: Promise.resolve({ v: evidence.version }) })).rejects.toThrow();
    process.env.GEKTA_MERCHANT_LEGAL_NAME = 'Changed after form render';
    await expect(GektaLegalDocumentPage({ params, searchParams: Promise.resolve(commitment) })).rejects.toThrow();
    // The ordinary public document route continues to display the actual current profile.
    expect(renderToStaticMarkup(await GektaLegalDocumentPage({ params }))).toContain('Changed after form render');
  });

  it('builds the actual registration form with its locale-bound commitment and no server key', async () => {
    process.env.REGISTRATION_DELIVERY_KEY = TEST_KEY;
    const page = await GektaRegisterPage({ searchParams: Promise.resolve({ lang: 'en' }) });
    const shown = page.props.consentPresentation;
    expect(verifyGektaConsentSnapshot(shown.snapshot, currentGektaLegalEvidence('en', 'GEKTA_REGISTRATION'), TEST_KEY)).not.toBeNull();
    expect(shown.termsHref).toContain('v=2026-08-12.2');
    expect(JSON.stringify(page.props)).not.toContain(TEST_KEY);
    expect(registrationConsentPresentation('en', 'short').snapshot).toBeNull();
  });
});

