    failed: 'Could not save your confirmation. Please try again.',
  },
  zh: {
    title: '开始之前',
    body: 'Gekta 使用人工智能帮助分析农业任务。回答可能需要核实，且不能替代专业人员。',
    accept: '继续即表示您接受',
