const REPOSITORY = String(process.env.GITHUB_REPOSITORY || '').trim();
const RELEASE_ISSUE_NUMBER = String(process.env.RELEASE_ISSUE_NUMBER || '').trim();

let stage = 'bootstrap';
let browser;

class AcceptanceFailure extends Error {
  constructor(code) {
    super(code);
    this.code = code;
  }
}

function fail(code) {
  throw new AcceptanceFailure(code);
}

function assert(condition, code) {
  if (!condition) fail(code);
}

function delay(milliseconds) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

function runGh(args) {
  const result = spawnSync('gh', args, {
    encoding: 'utf8',
    env: process.env,
    maxBuffer: 256 * 1024,
    timeout: 30_000,
  });
  return result.status === 0 ? result.stdout.trim() : '';
}

function publishOwnerProgress(marker) {
  assert(/^(?:7_DAYS|30_DAYS|LIFETIME)$/u.test(marker), 'GEKTA_OWNER_PROGRESS_MARKER_INVALID');
  assertExactMain();
  const body = [
    '## Gekta production owner ceremony progress',
    '',
    `- exact main: \`${TARGET_SHA}\``,
    `- observed entitlement: \`${marker}\``,
    `- run: \`${RUN_ID}\``,
  ].join('\n');
  const result = spawnSync('gh', [
    'issue', 'comment', RELEASE_ISSUE_NUMBER, '--repo', REPOSITORY, '--body', body,
  ], {
    encoding: 'utf8',
    env: process.env,
    maxBuffer: 64 * 1024,
    timeout: 30_000,
  });
  assert(result.status === 0, 'GEKTA_OWNER_PROGRESS_PUBLICATION_FAILED');
}

function assertExactMain() {
  const sha = runGh(['api', `repos/${REPOSITORY}/commits/main`, '--jq', '.sha']);
